SELECT
WHERE
ORDER BY e.batch_id, e.seq_no, e.id LIMIT #{offset}, #{limit}

SELECT e.id, e.entry_no AS entryNo, e.entry_name AS entryName, e.entry_name AS fileName, e.asset_count AS assetCount, u.file_name AS uploadName, fa.file_url AS fileUrl, fa.thumbnail_url AS thumbnailUrl, e.batch_id AS batchId, COALESCE(b.batch_name, b.batch_no) AS batchName, e.media_type AS mediaType, e.parse_status AS parseStatus, e.label_status AS labelStatus, e.review_status AS reviewStatus, e.review_round AS reviewRound, e.review_time AS reviewTime, e.assignee_id AS assigneeId, COALESCE(sa.nick_name, sa.user_name) AS assigneeName, e.reviewer_id AS reviewerId, COALESCE(sr.nick_name, sr.user_name) AS reviewerName, e.reject_count AS rejectCount, e.abandon_by AS abandonBy, e.skip_by AS skipBy, e.assign_time AS assignTime, e.create_time AS createTime, e.update_time AS updateTime, t.id AS taskId, t.task_name AS taskName, t.project_id AS projectId, p.project_name AS projectName, n.operator_id AS nodeOperatorId, COALESCE(sn.nick_name, sn.user_name) AS nodeOperatorName, n.status AS nodeStatus, n.prev_status AS nodePrevStatus, n.skip_by AS nodeSkipBy, n.abandon_by AS nodeAbandonBy, n.claim_time AS nodeClaimTime, (SELECT COUNT(*) FROM label_asset inv WHERE inv.entry_id = e.id AND inv.deleted = 0 AND inv.frame_flag = 'invalid') AS invalidFrameCount FROM label_data_entry e JOIN label_task t ON t.id = #{taskId} LEFT JOIN label_upload u ON u.id = e.upload_id LEFT JOIN label_asset_batch b ON b.id = e.batch_id LEFT JOIN label_project p ON p.id = t.project_id LEFT JOIN sys_user sa ON sa.user_id = e.assignee_id LEFT JOIN sys_user sr ON sr.user_id = e.reviewer_id
LEFT JOIN label_asset fa ON fa.id = e.first_asset_id AND fa.deleted = 0 JOIN label_entry_node n ON n.entry_id = e.id LEFT JOIN sys_user sn ON sn.user_id = n.operator_id WHERE
ORDER BY e.batch_id, e.seq_no, e.id LIMIT #{offset}, #{limit}


SELECT IFNULL(SUM(CASE WHEN  THEN 1 ELSE 0 END), 0) AS total,
       IFNULL(SUM(CASE WHEN n.status = 'pending'
                 AND 1 = 0
                 THEN 1 ELSE 0 END), 0) AS nodePending,
       IFNULL(SUM(CASE WHEN n.status = 'claimed'
                 AND n.operator_id = #{userId}
                 THEN 1 ELSE 0 END), 0) AS nodeClaimed,
       IFNULL(SUM(CASE WHEN n.status = 'skipped'
                 AND n.skip_by = #{userId}
                 THEN 1 ELSE 0 END), 0) AS nodeSkipped,
       IFNULL(SUM(CASE WHEN n.status = 'abandoned'
                 AND n.abandon_by = #{userId}
                 THEN 1 ELSE 0 END), 0) AS nodeAbandoned,
       IFNULL(SUM(CASE WHEN n.status = 'done'
                 AND n.operator_id = #{userId}
                 THEN 1 ELSE 0 END), 0) AS nodeDone
FROM label_data_entry e
JOIN label_task t ON t.id = #{taskId}
JOIN label_entry_node n ON n.entry_id = e.id
WHERE 
AND e.batch_id = #{batchId}

    AND n.operator_id = #{userId}

SELECT e.id, e.entry_no AS entryNo, e.entry_name AS entryName, e.asset_count AS assetCount,
fa.file_url AS fileUrl, fa.thumbnail_url AS thumbnailUrl, COALESCE(b.batch_name, b.batch_no) AS batchName, t.data_type AS mediaType, e.label_status AS labelStatus, e.review_status AS reviewStatus, e.assignee_id AS assigneeId, COALESCE(sa.nick_name, sa.user_name) AS assigneeName, e.reviewer_id AS reviewerId, COALESCE(sr.nick_name, sr.user_name) AS reviewerName, e.reject_count AS rejectCount, e.abandon_by AS abandonBy, e.skip_by AS skipBy, e.update_time AS updateTime, COALESCE(team.team_name, '未分组') AS teamName, n.node_key AS nodeKey, n.status AS nodeStatus, n.skip_by AS nodeSkipBy, n.abandon_by AS nodeAbandonBy, (SELECT COUNT(*) FROM label_asset inv WHERE inv.entry_id = e.id AND inv.deleted = 0 AND inv.frame_flag = 'invalid') AS invalidFrameCount FROM label_data_entry e JOIN label_task t ON t.id = #{taskId} AND t.deleted = 0 LEFT JOIN label_asset_batch b ON b.id = e.batch_id AND b.deleted = 0 LEFT JOIN label_asset fa ON fa.id = e.first_asset_id AND fa.deleted = 0 LEFT JOIN sys_user sa ON sa.user_id = e.assignee_id LEFT JOIN sys_user sr ON sr.user_id = e.reviewer_id
LEFT JOIN label_team team ON team.id = t.team_id AND team.deleted = 0 -- 「总览」按 entry 一行：拼上该 entry 冗余的 latest_node_id 指向的最新节点记录 -- （无记录则为 NULL；指针由 EntryNodeService 维护，软删记录按 NULL 处理，与原相关子查询口径一致） LEFT JOIN label_entry_node n ON n.id = e.latest_node_id AND n.deleted = 0 WHERE e.deleted = 0 AND e.task_id = #{taskId}
AND (e.label_status IS NULL OR e.label_status <> 'abandoned') AND (n.status IS NULL OR n.status <> 'abandoned') AND e.batch_id = #{batchId}
AND n.status IN #{s}
AND (e.entry_name LIKE CONCAT('%', #{keyword}, '%') OR e.entry_no LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY e.batch_id, e.seq_no, e.id LIMIT #{offset}, #{limit}

