SELECT t.entryId AS entryId, t.jobId AS jobId FROM ( SELECT e.id AS entryId, j.id AS jobId, ROW_NUMBER() OVER ( PARTITION BY e.id ORDER BY a.id, (j.assignee_id <=> e.assignee_id) DESC, j.id ) AS rn FROM label_data_entry e JOIN label_asset a ON a.entry_id = e.id AND a.deleted = 0 JOIN label_job_asset ja ON ja.asset_id = a.id JOIN label_job j ON j.id = ja.job_id AND j.task_id = #{taskId} AND j.deleted = 0 WHERE e.deleted = 0 AND e.id IN
#{eid}
) t WHERE t.rn = 1

